# Other account JSON-RPC methods
account/read {"refreshToken":false}      -> {account:{type:"chatgpt",email,planType}|{type:"apiKey"}, requiresOpenaiAuth}
account/login/start                      -> apiKey | chatgpt | chatgptDeviceCode | chatgptAuthTokens(experimental)
account/login/cancel {loginId}
account/logout
account/usage/read                       -> {summary:{lifetimeTokens,peakDailyTokens,longestRunningTurnSec,currentStreakDays,longestStreakDays},dailyUsageBuckets:[{startDate,tokens}]}
account/rateLimitResetCredit/consume {idempotencyKey, creditId?}  -> {outcome: reset|alreadyRedeemed|nothingToReset|noCredit}
account/workspaceMessages/read
account/sendAddCreditsNudgeEmail {creditType: credits|usage_limit}
# notifications (no id): account/updated, account/rateLimits/updated, thread/tokenUsage/updated

# Thread/turn JSON-RPC (for a persistent orchestrator instead of one process per task)
thread/start {model,cwd,approvalPolicy,sandbox,config,serviceName,ephemeral,...}  -> {thread:{id,sessionId,...}}   # NO caller-supplied id
thread/resume {threadId,...}
thread/fork {threadId, lastTurnId?, ephemeral?, ...}
thread/name/set {threadId,name}          # the ONLY caller-chosen handle; resumable by name from the CLI
thread/list / thread/read / thread/archive / thread/delete / thread/unsubscribe
turn/start {threadId, input:[{type:"text",text:"..."}]} / turn/steer / turn/interrupt
model/list {limit,includeHidden}
